function log(text){const row=document.createElement('div');row.className='log-entry';row.innerHTML=text;const box=$('#log');box.prepend(row);while(box.children.length>24)box.lastChild.remove()}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),1050)}
function rollDie(){const display=$('#rollDisplay');display.classList.remove('shake');void display.offsetWidth;display.classList.add('shake');return Math.floor(Math.random()*20)+1}
function current(){return heroes[state.active]}
function update(){
 const room=rooms[state.room];$('#roomCount').textContent=`${String(state.room+1).padStart(2,'0')} / 04`;$('#roomName').textContent=`${String(state.room+1).padStart(2,'0')} — ${room.name}`;
 $('#enemyName').textContent=room.enemy;$('#enemyHP').textContent=`${Math.max(0,state.enemyHp)} / ${room.hp} VIT`;$('#enemyArt').innerHTML=enemySvg(room.kind);$('#enemyWrap').classList.toggle('hidden',state.phase==='descend'||state.phase==='won'||state.phase==='lost');
 $('#objective').innerHTML=state.phase==='descend'?'<strong>Path clear:</strong> Catch your breath and descend':state.phase==='won'?'<strong>Objective complete:</strong> The Deepwyrm is defeated':state.phase==='lost'?'<strong>Party fallen:</strong> The dungeon claims another tale':`<strong>Objective:</strong> Defeat ${room.enemy}`;
 $('#progress').innerHTML=rooms.map((_,i)=>`<i class="${i<state.room?'done':i===state.room?'current':''}"></i>`).join('');
 $('#fighterArt0').innerHTML=heroArt(false);$('#fighterArt1').innerHTML=heroArt(true);
 heroes.forEach((h,i)=>{const card=$(`#fighter${i}`);card.classList.toggle('down',h.hp<=0);const fill=$(`#hpFill${i}`);if(fill)fill.style.width=`${Math.max(0,h.hp)/h.maxHp*100}%`;const num=$(`#hpNum${i}`);if(num)num.textContent=`${Math.max(0,h.hp)} / ${h.maxHp}`;const mana=$(`#manaFill${i}`);if(mana)mana.style.width=`${h.mana}/${h.maxMana}*100%`;const manaNum=$(`#manaNum${i}`);if(manaNum)manaNum.textContent=`${h.mana} / ${h.maxMana}`;const cardPanel=$(`#heroCard${i}`);if(cardPanel){cardPanel.classList.toggle('active',state.phase==='combat'&&state.active===i);const pill=$(`#pill${i}`);pill.textContent=h.hp<=0?'DOWN':state.phase==='combat'&&state.active===i?'YOUR TURN':state.acted[i]?'DONE':'READY';pill.style.color=h.hp<=0?'var(--red)':state.phase==='combat'&&state.active===i?'var(--gold)':'var(--muted)';}});
 $('#roundLabel').textContent=`ROUND ${state.round}`;renderActions();
}
function renderParty(){ $('#partyHeroes').innerHTML=heroes.map((h,i)=>`<article class="hero-card" id="heroCard${i}"><div class="hero-row"><div class="avatar ${i?'mage':''}">${h.icon}</div><div class="hero-info"><div class="hero-name">${h.name}</div><div class="hero-class">${h.role.toUpperCase()}</div></div><span class="turn-pill" id="pill${i}"></span></div><div class="bar-row"><span>VITALITY</span><span id="hpNum${i}">${h.hp} / ${h.maxHp}</span></div><div class="bar"><div class="bar-fill" id="hpFill${i}"></div></div><div class="bar-row"><span>FOCUS</span><span id="manaNum${i}">${h.mana} / ${h.maxMana}</span></div><div class="bar"><div class="bar-fill mana" id="manaFill${i}"></div></div><div class="stats"><span class="stat"><b>+${h.stat}</b> ${h.statName}</span><span class="stat"><b>${i?11:9}+</b> SPECIAL</span><span class="stat special">✦ ${state.potions} TONIC</span></div></article>`).join('')}
function renderActions(){const actor=current();const actions=$('#actions');if(state.phase==='descend'){ $('#turnLabel').textContent='ROOM CLEARED';actions.innerHTML=`<button class="action wide" data-action="descend"><span class="action-icon">⇣</span><span class="action-copy"><span class="action-name">Descend to the next room</span><span class="action-note">Recover 5 vitality · restore 1 focus</span></span><span class="die-icon">GO</span></button>`;return}if(state.phase!=='combat'){ $('#turnLabel').textContent=state.phase==='won'?'VICTORY':'EXPEDITION ENDED';actions.innerHTML='<button class="action wide" data-action="restart"><span class="action-icon">↻</span><span class="action-copy"><span class="action-name">Begin a new expedition</span><span class="action-note">Your next legend starts here</span></span><span class="die-icon">GO</span></button>';return}
 $('#turnLabel').textContent=`${actor.name.toUpperCase()}’S TURN`;const specialName=state.active===0?'Shield bash':'Starfall';const specialDesc=state.active===0?'9+ · 8 damage · costs 1 focus':'11+ · 10 damage · costs 2 focus';const specialCost=state.active===0?1:2;const specialReady=actor.mana>=specialCost;
 actions.innerHTML=`<button class="action" data-action="attack"><span class="action-top"><span class="action-icon">⚔</span><span class="die-icon">D20</span></span><span class="action-name">Strike</span><span class="action-note">D20 + ${actor.stat} vs ${rooms[state.room].guard} guard</span></button><button class="action" data-action="special" ${specialReady?'':'disabled'}><span class="action-top"><span class="action-icon">${state.active?'✧':'⬟'}</span><span class="die-icon">${specialReady?'D20':`−${specialCost} FOCUS`}</span></span><span class="action-name">${specialName}</span><span class="action-note">${specialReady?specialDesc:'Not enough focus'}</span></button><button class="action" data-action="guard"><span class="action-top"><span class="action-icon">◈</span><span class="die-icon">D20</span></span><span class="action-name">Brace</span><span class="action-note">8+ · reduce next hit by 3</span></button><button class="action" data-action="potion" ${state.potions>0?'':'disabled'}><span class="action-top"><span class="action-icon">♧</span><span class="die-icon">D20</span></span><span class="action-name">Healing tonic</span><span class="action-note">${state.potions>0?'7+ · restore 10 vitality':'No tonics left'}</span></button>`;
}
function resolveHeroTurn(){state.acted[state.active]=true;const next=heroes.findIndex((h,i)=>h.hp>0&&!state.acted[i]);if(next>=0){state.active=next;update();return}monsterTurn()}
function monsterTurn(){if(state.enemyHp<=0||state.phase!=='combat')return;const room=rooms[state.room];const targets=heroes.filter(h=>h.hp>0);if(!targets.length){endGame(false);return}let target=targets.sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];const roll=rollDie();const hit=roll>=8;if(hit){let damage=room.damage[0]+Math.floor(Math.random()*(room.damage[1]-room.damage[0]+1));if(target.guarding){damage=Math.max(1,damage-3);target.guarding=false;log(`<strong>${target.name}</strong> braces against the blow, absorbing 3 damage.`)}target.hp=Math.max(0,target.hp-damage);log(`<span class="bad">${room.enemy} rolls ${roll} and hits ${target.name} for ${damage} damage.</span>`);showToast(`−${damage} ${target.name.toUpperCase()}`);if(target.hp===0)log(`<span class="bad"><strong>${target.name}</strong> has fallen!</span>`)}else{log(`<strong>${room.enemy}</strong> rolls ${roll} and misses in a shower of sparks.`);showToast('THE ENEMY MISSES')}
 if(heroes.every(h=>h.hp<=0)){update();endGame(false);return}state.round++;state.acted=[false,false];state.active=heroes[0].hp>0?0:1;update();$('#rollHint').textContent='The enemy takes its turn';$('#rollResult').innerHTML=`<b>${roll}</b> ${hit?'ENEMY HIT':'ENEMY MISSED'}`}
function perform(action){if(state.phase==='descend'&&action==='descend'){nextRoom();return}if(action==='restart'){resetGame();return}if(state.phase!=='combat')return;const actor=current();const room=rooms[state.room];let roll=rollDie();let result='';let detail='';$('#rollHint').textContent=`${actor.name} rolls a d20`;$('#rollResult').innerHTML=`<b>${roll}</b> ...`;
 if(action==='attack'){const total=roll+actor.stat;const hit=roll!==1&&(roll===20||total>=room.guard);if(hit){const damage=roll===20?11+actor.stat:6+Math.floor(actor.stat/2);state.enemyHp=Math.max(0,state.enemyHp-damage);result=`${roll===20?'CRITICAL! ':''}${damage} DAMAGE`;detail=`<strong>${actor.name}</strong> rolls ${roll} + ${actor.stat} = ${total} and strikes for <span class="gold">${damage} damage</span>.`;showToast(roll===20?'CRITICAL STRIKE!':`−${damage} ${room.enemy.toUpperCase()}`)}else{result=`${total} · MISS`;detail=`<strong>${actor.name}</strong> rolls ${roll} + ${actor.stat} = ${total}; the blow glances off.`;showToast('THE STRIKE MISSES')}}
 else if(action==='special'){const cost=state.active===0?1:2,threshold=state.active===0?9:11,damage=state.active===0?8:10;actor.mana-=cost;const success=roll!==1&&(roll===20||roll>=threshold);if(success){const hitDamage=roll===20?damage+5:damage;state.enemyHp=Math.max(0,state.enemyHp-hitDamage);result=`${roll===20?'CRITICAL! ':''}${hitDamage} DAMAGE`;detail=`<strong>${actor.name}</strong> unleashes ${state.active===0?'Shield bash':'Starfall'} (roll ${roll}) for <span class="gold">${hitDamage} damage</span>!`;showToast(`${state.active?'STARBURST':'SHIELD BASH'}!`)}else{result=`${roll} · FIZZLE`;detail=`<strong>${actor.name}</strong> tries ${state.active===0?'Shield bash':'Starfall'}, but the magic fizzles (rolled ${roll}).`;showToast('THE MAGIC FIZZLES')}}
 else if(action==='guard'){const success=roll>=8;if(success){actor.guarding=true;result=`${roll} · BRACED`;detail=`<strong>${actor.name}</strong> rolls ${roll} and braces for the next blow.`;showToast(`${actor.name.toUpperCase()} IS BRACED`)}else{result=`${roll} · TOO SLOW`;detail=`<strong>${actor.name}</strong> rolls ${roll}, but fails to get into a defensive stance.`;showToast('BRACE FAILED')}}
 else if(action==='potion'){const target=[...heroes].sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];const success=roll+actor.stat>=10&&roll!==1;if(success&&state.potions>0){state.potions--;const wasDown=target.hp===0;target.hp=Math.min(target.maxHp,target.hp+10);target.alive=true;result=`${roll} · +${wasDown?target.hp:Math.min(10,target.maxHp-(target.hp-10))} VIT`;detail=`<strong>${actor.name}</strong> rolls ${roll} and gives ${target.name} a tonic. <span class="gold">${target.name} recovers 10 vitality.</span>`;if(wasDown){state.acted[heroes.indexOf(target)]=true;detail+=` ${target.name} returns to the fight!`}showToast(`${target.name.toUpperCase()} HEALED`)}else{result=`${roll} · NO EFFECT`;detail=`<strong>${actor.name}</strong> rolls ${roll}; the tonic slips away before it can be used.`;showToast('TONIC MISSED')}}
 $('#rollHint').textContent=`${actor.name} · ${action==='attack'?'Strike':action==='special'?(state.active===0?'Shield bash':'Starfall'):action==='guard'?'Brace':'Healing tonic'}`;$('#rollResult').innerHTML=`<b>${roll}</b> ${result}`;log(detail);
 const scene=$('#scene');scene.classList.remove('splash');void scene.offsetWidth;scene.classList.add('splash');if(state.enemyHp<=0){state.enemyHp=0;update();log(`<strong>${room.enemy}</strong> is defeated! The passage opens.`);showToast('FOE DEFEATED');state.phase='descend';update();return}resolveHeroTurn();update();}
