function endGame(won){state.phase=won?'won':'lost';update();$('#modalEmblem').textContent=won?'✧':'☠';$('#modalTitle').textContent=won?'The Deepwyrm is vanquished':'The party has fallen';$('#modalText').textContent=won?'Varkul’s last roar shakes dust from the ancient ceiling. Together, you conquered the Hollow Below. The realm will remember your names.':`The party made it to room ${state.room+1} before the dungeon claimed them. Every legend ends somewhere—but yours can begin again.`;$('#modalButton').textContent=won?'PLAY AGAIN':'TRY AGAIN';$('#overlay').classList.add('open');$('#modalButton').onclick=()=>{resetGame()}}
