$('#actions').addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn&&!btn.disabled)perform(btn.dataset.action)});$('#resetBtn').addEventListener('click',()=>{$('#modalEmblem').textContent='✦';$('#modalTitle').textContent='Start a new expedition?';$('#modalText').textContent='Your current adventure will end. Bram and Nyx will be restored to full strength.';$('#modalButton').textContent='START OVER';$('#overlay').classList.add('open');$('#modalButton').onclick=resetGame});$('#helpBtn').addEventListener('click',()=>{$('#modalEmblem').textContent='⚄';$('#modalTitle').textContent='How to play';$('#modalText').innerHTML='Two players share a party. Pass the device so <b>Bram</b> and <b>Nyx</b> each take one turn per round. Strike: roll a d20 + your stat and meet the foe’s guard. Specials spend focus; Brace reduces the next hit, and a tonic heals your most injured hero. Clear four rooms to win!';$('#modalButton').textContent='GOT IT';$('#overlay').classList.add('open');$('#modalButton').onclick=()=>$('#overlay').classList.remove('open')});
